def _create_logger():
    log_dir = os.path.join(os.path.expanduser('~'), 'taf.sbts.browser_server_logs')
    log_file_name = 'taf.sbts.browser_server.log'
    log_file_path = os.path.join(log_dir, log_file_name)

    if not os.path.exists(log_dir):
        os.makedirs(log_dir)

    log = logging.getLogger('taf.sbts.browser_server')
    log.setLevel(logging.DEBUG)

    handler = logging.handlers.RotatingFileHandler(log_file_path, maxBytes=1024 * 256, backupCount=5)
    handler.setLevel(logging.DEBUG)
    formatter = logging.Formatter('%(asctime)s - [%(levelname)s] - %(message)s')
    handler.setFormatter(formatter)
    log.addHandler(handler)

    # to console
    log.addHandler(logging.StreamHandler())

    return log


LOGGER = _create_logger()

# lock for sending messages
LOCK = Lock()

