class TraceStore(object):
    def __init__(self):
        self._objects = {}

    def add(self, value, alias=None):
        alias = self._get_alias(alias)
        if alias in self._objects:
            LOGGER.debug("Alias ({}) already exists".format(alias))
        self._objects[alias] = value

    def get(self, alias=None):
        alias = self._get_alias(alias)
        if alias not in self._objects:
            LOGGER.warning("Provided alias ({}) doesn't exist.".format(alias))
            return None
        return self._objects[alias]

    def remove_all(self):
        self._objects = {}

    def _get_alias(self, alias):
        return "default" if alias is None else alias

    def __iter__(self):
        return (each for each in self._objects.values())


TRACE_STORE = TraceStore()


class DspResources(object):
    def __init__(self):
        self.msm = None
        self.esm = None

        self.available_board_ids = set()

        self._resources = None

    def set_resources(self, msm, esm):

        FSMr3 = 'FSMr3'
        FSMr4 = 'FSMr4'
        NO = None

        self.msm = msm
        self.esm = esm

        _set_resources = {
            (FSMr3, NO): self._set_for_3_none,
            (FSMr4, NO): self._set_for_4_none,
            (FSMr3, FSMr3): self._set_for_3_3,
            (FSMr4, FSMr4): self._set_for_4_4,
            (FSMr4, FSMr3): self._set_for_4_3
        }.get(
            (self.msm, self.esm)
        )

        _set_resources()

    @property
    def board_ids(self):
        return sorted(
            chain.from_iterable([board_ids for board_ids, _, _, _ in self._resources])
        )

    def get_chip_ids_for_board(self, board):
        # type: (int) -> List
        for board_ids, chip_ids, _, _ in self._resources:
            if board in board_ids:
                return chip_ids
        raise RuntimeError('Incorrect board id: {}'.format(board))

    def get_cpu_ids_for_board(self, board):
        # type: (int) -> List
        for board_ids, _, cpu_ids, _ in self._resources:
            if board in board_ids:
                return cpu_ids
        raise RuntimeError('Incorrect board id: {}'.format(board))

    def get_system_type_for_board(self, board):
        # type: (int) -> int
        for board_ids, _, _, system_type in self._resources:
            if board in board_ids:
                return system_type
        raise RuntimeError('Incorrect board id: {}'.format(board))

    def get_cpu_ids_for_chip(self, board, chip):
        # type: (int, int) -> List
        candidate_cpu_ids = []
        for board_ids, chip_ids, cpu_ids, _ in self._resources:
            if board in board_ids:
                candidate_cpu_ids = cpu_ids
                break

        return [
            cpu_id for cpu_id in candidate_cpu_ids if ((cpu_id >> FOUR_BITS) << FOUR_BITS) == chip
        ]

    def _set_for_4_none(self):
        self._resources = [
            (BOARD_KEPLER, CHIP_KEPLER, CPU_KEPLER, SYSTEM_TYPE_KEPLER)
        ]

    def _set_for_3_none(self):
        self._resources = [
            (BOARD_NYQUIST, CHIP_NYQUIST, CPU_NYQUIST, SYSTEM_TYPE_NYQUIST)
        ]

    def _set_for_3_3(self):
        self._resources = [
            (BOARD_NYQUIST, CHIP_NYQUIST, CPU_NYQUIST, SYSTEM_TYPE_NYQUIST),
            (BOARD_NYQUIST_EXT, CHIP_NYQUIST, CPU_NYQUIST, SYSTEM_TYPE_NYQUIST)
        ]

    def _set_for_4_4(self):
        self._resources = [
            (BOARD_NYQUIST, CHIP_KEPLER, CPU_KEPLER, SYSTEM_TYPE_KEPLER),
            (BOARD_NYQUIST_EXT, CHIP_KEPLER, CPU_KEPLER, SYSTEM_TYPE_KEPLER)
        ]

    def _set_for_4_3(self):
        self._resources = [
            (BOARD_NYQUIST, CHIP_KEPLER, CPU_KEPLER, SYSTEM_TYPE_KEPLER),
            (BOARD_NYQUIST_EXT, CHIP_NYQUIST, CPU_NYQUIST, SYSTEM_TYPE_NYQUIST)
        ]


DSP_RESOURCES = DspResources()
